import{_ as t,C as e,o as s,c as h,j as a,E as l,a as o,a2 as r}from"./chunks/framework.C21TwvGF.js";const j=JSON.parse(`{"title":"3-dars (Mentor). UI va UX ning Game designdagi roli: Interfeys tiplari va HUD arxitekturasi","description":"","frontmatter":{"title":"3-dars (Mentor). UI va UX ning Game designdagi roli: Interfeys tiplari va HUD arxitekturasi","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":1,"link":"/mentor/9-sinf-game/hafta-01/"},"g":3,"title":"UI va UX ning Game designdagi roli: Interfeys tiplari va HUD arxitekturasi","lead":"Eng yaxshi o'yin interfeysi — bu o'yinchi sezmaydigan, ammo har qanday vaziyatda unga ko'maklashadigan ko'rinmas do'stdir!","slide":"/slaydlar/9-sinf-game/hafta-01/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-01/dars-3-test.html","student_link":"/9-sinf-game/hafta-01/dars-3","tabs":[{"g":1,"link":"/mentor/9-sinf-game/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/9-sinf-game/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/9-sinf-game/hafta-01/dars-3","current":true}],"prev":{"g":2,"title":"O‘yinlarning tarixi va janrlari: O'yin evolyutsiyasi, janrlar tasnifi va madaniy ta'siri","link":"/mentor/9-sinf-game/hafta-01/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-01/dars-3.md","filePath":"mentor/9-sinf-game/hafta-01/dars-3.md"}`),d={name:"mentor/9-sinf-game/hafta-01/dars-3.md"},m={class:"blk"},g={id:"dars-rejasi",tabindex:"-1"},y={class:"blk"},u={id:"mentor-konspekti",tabindex:"-1"},k={class:"blk"},q={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},f={class:"blk"},v={id:"tezkor-nazorat-savollari",tabindex:"-1"},b={class:"blk"},c={id:"uyga-vazifa",tabindex:"-1"};function p(z,i,U,_,x,D){const n=e("Icon");return s(),h("div",null,[a("div",m,[a("h2",g,[l(n,{name:"file-text"}),i[0]||(i[0]=o(" Dars rejasi ",-1)),i[1]||(i[1]=a("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),i[2]||(i[2]=r("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga video o&#39;yinlarda foydalanuvchi interfeysi (UI) va foydalanuvchi tajribasi (UX) tushunchalari, ularning o&#39;zaro farqi va uyg&#39;unligi, o&#39;yin interfeysining 4 ta asosiy tipi (Diyegetik, Nodiyegetik, Fazoviy va Meta-interfeys) hamda o&#39;yin ichidagi doimiy axborot displeyi — HUD (Heads-Up Display) elementlarini loyihalashni o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar UI va UX farqini aniq ajrata oladi; har qanday o&#39;yindagi interfeys elementlarini 4 tip bo&#39;yicha toifalashni o&#39;rganadi; o&#39;yinchini chalg&#39;itmaydigan, qulay va immersiv HUD interfeysini loyihalay oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (O&#39;yinlar tarixi va janrlar): 10 daqiqa</li><li>Yangi mavzu: UI va UX tushunchalari hamda ularning o&#39;zaro bog&#39;liqligi: 20 daqiqa</li><li>4 ta interfeys tipi: Diyegetik, Nodiyegetik, Fazoviy va Meta: 25 daqiqa</li><li>HUD elementlari va qulaylik (UX) mezonlari: 15 daqiqa</li><li>Tezkor savollar va dars xulosasi: 10 daqiqa</li></ul></li></ul><hr>",2))]),a("div",y,[a("h2",u,[l(n,{name:"file-text"}),i[3]||(i[3]=o(" Mentor konspekti ",-1)),i[4]||(i[4]=a("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),i[5]||(i[5]=r('<h3 id="_1-ui-va-ux-nima-ular-o-yinda-qanday-o-zaro-ta-sirlashadi" tabindex="-1">1. UI va UX nima? Ular o&#39;yinda qanday o&#39;zaro ta&#39;sirlashadi? <a class="header-anchor" href="#_1-ui-va-ux-nima-ular-o-yinda-qanday-o-zaro-ta-sirlashadi" aria-label="Permalink to &quot;1. UI va UX nima? Ular o&#39;yinda qanday o&#39;zaro ta&#39;sirlashadi?&quot;">​</a></h3><ul><li><strong>UI (User Interface — Foydalanuvchi interfeysi):</strong> O&#39;yinchi ekranda ko&#39;radigan barcha vizual elementlar to&#39;plami. Tugmalar, menyular, shriftlar, piktogrammalar, ranglar sxemasi va animatsiyalar. <ul><li><em>Savol:</em> &quot;O&#39;yin qanday ko&#39;rinadi?&quot;</li></ul></li><li><strong>UX (User Experience — Foydalanuvchi tajribasi):</strong> O&#39;yinchining o&#39;yin bilan muloqot qilganda oladigan umumiy hissiyoti, qulayligi, boshqaruvning silliqligi va tushunarliligi. <ul><li><em>Savol:</em> &quot;O&#39;yin qanday his qilinadi?&quot;</li></ul></li><li><strong>UI va UX uyg&#39;unligi:</strong><ul><li>UX dizayner foydalanuvchi harakat oqimini (qaysi tugmadan keyin qaysi oyna ochilishini) loyihalaydi;</li><li>UI dizayner bu tuzilmaga go&#39;zal vizual libos kiydiradi (ranglar, ikonalar, shriftlar);</li><li>Agar UI chiroyli bo&#39;lib, lekin tugmalar noqulay joylashgan bo&#39;lsa $\\to$ o&#39;yinchi asabiylashadi va o&#39;yindan chiqib ketadi (yomon UX).</li></ul></li></ul><h3 id="_2-o-yin-interfeysining-4-ta-asosiy-tipi" tabindex="-1">2. O&#39;yin interfeysining 4 ta asosiy tipi <a class="header-anchor" href="#_2-o-yin-interfeysining-4-ta-asosiy-tipi" aria-label="Permalink to &quot;2. O&#39;yin interfeysining 4 ta asosiy tipi&quot;">​</a></h3><p>Game Design nazariyasida interfeys elementlari o&#39;yin olamiga (Fiction) va fazoga (Space) nisbatan 4 turga bo&#39;linadi:</p><ol><li><strong>Diyegetik interfeys (Diegetic UI):</strong><ul><li>O&#39;yin olamining ichki qismi hisoblanadi. Uni ham o&#39;yinchi, ham o&#39;yin ichidagi bosh qahramon ko&#39;ra oladi!</li><li><em>Misollar:</em> <em>Dead Space</em> o&#39;yinida Ayzek skafandri umurtqasidagi salomatlik indikatori; <em>Metro 2033</em>dagi qo&#39;l soati va gazoblok filtr taymeri; <em>Far Cry 2</em> yoki <em>GTA V</em>da qahramon qo&#39;lidagi haqiqiy xarita va smartfon.</li><li><em>Afzalligi:</em> O&#39;yin olamiga to&#39;liq sho&#39;ng&#39;ish (Immersion) hissini beradi.</li></ul></li><li><strong>Nodiyegetik interfeys (Non-Diegetic UI):</strong><ul><li>O&#39;yin olamidan tashqarida bo&#39;lib, to&#39;g&#39;ridan-to&#39;g&#39;ri ekran ustiga qo&#39;yiladi. O&#39;yin ichidagi personajlar bu ma&#39;lumotni ko&#39;rmaydi.</li><li><em>Misollar:</em> Ekranning burchagidagi qizil sog&#39;lik chizig&#39;i, o&#39;q-dorilar soni hisoblagichi, <em>Super Mario</em>dagi tangalar va vaqt taymeri.</li><li><em>Afzalligi:</em> Bajarish juda oson, barcha kerakli ma&#39;lumotlarni o&#39;yinchiga aniq va tezkor yetkazadi.</li></ul></li><li><strong>Fazoviy interfeys (Spatial UI):</strong><ul><li>3D o&#39;yin fazosiga joylashtiriladi, lekin virtual personajlar undan bexabar bo&#39;ladi.</li><li><em>Misollar:</em> MMORPG (<em>World of Warcraft</em>) o&#39;yinlarida personajlar va dushmanlar boshi ustidagi ism taxtachalari; yo&#39;l ko&#39;rsatuvchi 3D strelkalar; nishonga olish doiralari.</li><li><em>Afzalligi:</em> Ekranni to&#39;ldirmasdan, kerakli obyektning aynan o&#39;ziga ma&#39;lumot bog&#39;lash.</li></ul></li><li><strong>Meta-interfeys (Meta UI):</strong><ul><li>O&#39;yin voqeligining bir qismi emas, lekin qahramonning jismoniy holatini o&#39;yinchiga his qildiruvchi vizual/audio effektlar.</li><li><em>Misollar:</em> O&#39;yinchi yaralanganda ekranning qizarishi yoki chetlariga qon sachrashi; suv ostiga tushganda ekranda paydo bo&#39;ladigan pufakchalar; zarba tekkanda geympadning tebranishi (rumble).</li></ul></li></ol><h3 id="_3-hud-heads-up-display-arxitekturasi" tabindex="-1">3. HUD (Heads-Up Display) arxitekturasi <a class="header-anchor" href="#_3-hud-heads-up-display-arxitekturasi" aria-label="Permalink to &quot;3. HUD (Heads-Up Display) arxitekturasi&quot;">​</a></h3><p>HUD — bu o&#39;yin jarayonida ekranda doimiy yoki vaqtincha ko&#39;rinib turuvchi barcha axborot panellari majmuasidir.</p><ul><li><strong>Asosiy elementlari:</strong><ol><li><em>Health / Mana Bar:</em> Qahramonning hayotiy quvvati.</li><li><em>Mini-map (Mini xarita):</em> Hudud va nishonlar yo&#39;nalishi.</li><li><em>Ammo counter (O&#39;q-dorilar):</em> Qurol zaxirasi.</li><li><em>Score / Currency:</em> Yig&#39;ilgan tangalar yoki ochkolar.</li></ol></li><li><strong>HUD dizaynining oltin qoidalari:</strong><ul><li><em>Ekranni to&#39;ldirib yubormaslik:</em> O&#39;yin jarayoni markazda bo&#39;lishi kerak.</li><li><em>Kontrast va o&#39;qilishi oson shrift:</em> Har qanday fon (qor, o&#39;rmon, qorong&#39;u xona)da ham ma&#39;lumot aniq ko&#39;rinsin.</li><li><em>Dinamik yashirinish (Contextual HUD):</em> Jang bo&#39;lmaganda sog&#39;lik panelining avtomatik yo&#39;qolishi.</li></ul></li></ul><hr>',9))]),a("div",k,[a("h2",q,[l(n,{name:"file-text"}),i[6]||(i[6]=o(" Amaliy topshiriqlar va yechimlar ",-1)),i[7]||(i[7]=a("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),i[8]||(i[8]=r('<h3 id="_1-topshiriq-interfeys-elementlarini-toifalash-oson" tabindex="-1">1-topshiriq. Interfeys elementlarini toifalash (oson) <a class="header-anchor" href="#_1-topshiriq-interfeys-elementlarini-toifalash-oson" aria-label="Permalink to &quot;1-topshiriq. Interfeys elementlarini toifalash (oson)&quot;">​</a></h3><p>Quyidagi 4 ta interfeys elementini 4 ta tipga (Diyegetik, Nodiyegetik, Fazoviy, Meta) ajrating:</p><ol><li>Qahramon avtomobil minib ketayotganda torpedadagi haqiqiy spidometr ko&#39;rsatkichi;</li><li>Ekranning yuqori chap burchagidagi qizil yurakchalar (jon soni);</li><li>Dushmanning boshi ustida aylanib turgan &quot;sariq yulduzchalar&quot; (gangiganlik belgisi);</li><li>Qahramon qahraton sovuqda qolganda ekranning muzlab borishi.</li></ol><p><strong>Yechim:</strong></p><ol><li>Torpedadagi spidometr $\\to$ <strong>Diyegetik</strong> (o&#39;yin olami va qahramon ko&#39;radi);</li><li>Burchakdagi yurakchalar $\\to$ <strong>Nodiyegetik</strong> (faqat o&#39;yinchi ko&#39;radi);</li><li>Bosh ustidagi yulduzchalar $\\to$ <strong>Fazoviy (Spatial)</strong> (3D fazoda joylashgan);</li><li>Ekranning muzlashi $\\to$ <strong>Meta-interfeys</strong> (qahramon hissini ekranda aks ettiradi).</li></ol><h3 id="_2-topshiriq-ui-ux-muammosini-aniqlash-va-tuzatish-o-rta" tabindex="-1">2-topshiriq. UI/UX muammosini aniqlash va tuzatish (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-ui-ux-muammosini-aniqlash-va-tuzatish-o-rta" aria-label="Permalink to &quot;2-topshiriq. UI/UX muammosini aniqlash va tuzatish (o&#39;rta)&quot;">​</a></h3><p>O&#39;yinda o&#39;yinchi dushman bilan jang qilayotganda uning o&#39;q-dorilari tugab qoladi. Ekranning pastki o&#39;ng burchagida juda kichik kulrang shrift bilan &quot;Ammo: 0&quot; yozilgan bo&#39;lsa-da, o&#39;yinchi jang paytida buni sezmaydi va nima uchun qurol otmayotganini tushunmay vafot etadi. Ushbu vaziyatda UI va UX jihatdan qanday yechimlar qo&#39;llash kerak?</p><p><strong>Yechim:</strong></p><ul><li><strong>UI yechimi:</strong> O&#39;q tugaganda nishon yonida yoki ekranning o&#39;rtasida qizil ogohlantiruvchi belgi chiqarish yoki qurol indikatorini miltillovchi qizil rangga aylantirish.</li><li><strong>UX va Audio yechimi:</strong> Bo&#39;sh zatvorning xos quruq &quot;chertilish&quot; (click) ovozini chiqarish, qahramonning &quot;Reload!&quot; deb qichqirishi yoki geympadning qisqa titrashi. Shunda o&#39;yinchi ekranning burchagiga qaramasdan ham muammoni intuitiv tushunadi.</li></ul><h3 id="_3-topshiriq-mobil-o-yin-uchun-minimalist-hud-loyihalash-qiyin" tabindex="-1">3-topshiriq. Mobil o&#39;yin uchun minimalist HUD loyihalash (qiyin) <a class="header-anchor" href="#_3-topshiriq-mobil-o-yin-uchun-minimalist-hud-loyihalash-qiyin" aria-label="Permalink to &quot;3-topshiriq. Mobil o&#39;yin uchun minimalist HUD loyihalash (qiyin)&quot;">​</a></h3><p>Mobil telefonlar ekrani kichik bo&#39;lgani sababli barcha ma&#39;lumotlarni chiqarish ekranni to&#39;ldirib yuboradi. O&#39;rmonda omon qolish (Survival) janridagi mobil o&#39;yin uchun qanday minimalistik va qulay HUD tizimini taklif qilasiz?</p><p><strong>Yechim:</strong></p><ol><li><strong>Dinamik HUD:</strong> Doimiy barcha ko&#39;rsatkichlarni ko&#39;rsatmaslik. O&#39;yinchi xavfsiz holatda yurganda barcha panellar yashirinadi (to&#39;liq toza ekran).</li><li><strong>Diyegetik belgilar:</strong> Qahramonning charchog&#39;i ekranda og&#39;ir nafas olish ovozi bilan beriladi; qorong&#39;ulik esa qo&#39;lidagi mash&#39;alaning tutashi bilan o&#39;lchanadi.</li><li><strong>Qalqib chiquvchi piktogrammalar:</strong> Ochlik yoki chanqoqlik kritik darajaga yetgandagina ekranning chetida kichik piktogramma paydo bo&#39;ladi.</li><li><strong>Boshqaruv:</strong> Ekranda ortiqcha vizual joystik chizmasdan, ekranning chap yarmini erkin siljitish orqali boshqaruvga moslash.</li></ol><hr>',14))]),a("div",f,[a("h2",v,[l(n,{name:"file-text"}),i[9]||(i[9]=o(" Tezkor nazorat savollari ",-1)),i[10]||(i[10]=a("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),i[11]||(i[11]=r("<ol><li>Qaysi interfeys turini ham o&#39;yinchi, ham o&#39;yin qahramoni birdek ko&#39;ra oladi? <ul><li><em>Javob:</em> Diyegetik interfeys.</li></ul></li><li>HUD qisqartmasi nimani anglatadi? <ul><li><em>Javob:</em> Heads-Up Display (Boshni ko&#39;targan holda ko&#39;rinuvchi axborot paneli).</li></ul></li><li>Zarba yeganda ekranning qon sachrab qizarishi qaysi interfeys turiga kiradi? <ul><li><em>Javob:</em> Meta-interfeys.</li></ul></li><li>UI va UX o&#39;rtasidagi asosiy farq nimada? <ul><li><em>Javob:</em> UI — tashqi ko&#39;rinish va elementlar, UX — boshqaruv qulayligi va umumiy tajriba.</li></ul></li></ol><hr>",2))]),a("div",b,[a("h2",c,[l(n,{name:"house"}),i[12]||(i[12]=o(" Uyga vazifa ",-1)),i[13]||(i[13]=a("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),i[14]||(i[14]=a("p",null,"O'zingiz eng ko'p o'ynaydigan bitta o'yinni tanlang:",-1)),i[15]||(i[15]=a("ol",null,[a("li",null,"Undagi HUD elementlarining to'liq ro'yxatini yozing (Health bar, xarita, qurol va h.k.);"),a("li",null,"O'yindan 4 ta interfeys turiga (Diyegetik, Nodiyegetik, Fazoviy, Meta) mos keluvchi 1 tadan aniq element topib yozing;"),a("li",null,"Ushbu o'yinda o'zingizga yoqmagan 1 ta noqulay interfeys jihatini tanqid qiling va qanday yaxshilash mumkinligini ayting.")],-1))])])}const T=t(d,[["render",p]]);export{j as __pageData,T as default};
